// World (test/helpers/world.ts) with witnessQuorum 0, V voters; register, publishManifest, ceremony, open, cast V ballots, close
const tal = await w.get(`/api/v1/elections/${w.electionId}/tally`);
assert.notEqual(tal.json.aggregate_seq, null); assert.equal(tal.json.n_counted, V);
for (let k = 0; k < 4; k++) {
  const t0 = performance.now();
  const r = await w.get(`/api/v1/elections/${w.electionId}/tally/draft`); // unauthenticated, no shares posted
  runs.push({ status: r.status, ms: performance.now() - t0 });
}
// cost of the work the handler repeats on every call
const an = analyzeBallotLog(w.params, new Set(w.rollHex), env, open, close);
const t0 = performance.now(); aggregate(w.params, an.counted); const aggMs = performance.now() - t0;
const big = Array.from({ length: 2000 }, (_, i) => an.counted[i % an.counted.length]);
const t1 = performance.now(); aggregate(w.params, big); const agg2000 = performance.now() - t1;
for (const r of runs) { assert.equal(r.status, 409); assert.ok(r.ms >= aggMs * 0.5); }

const w = await fullElection('vb02');
const bytes = await exportQvb(w);
for (const q of [`?org_id=${w.orgId}`, `?org_id=${w.orgId}&manifest_hash=${'0'.repeat(64)}`]) {
  const h = monitorEventLoopDelay({ resolution: 5 }); h.enable();
  const t0 = performance.now();
  const r = await upload(w, bytes, { query: q }); assert.equal(r.status, 202);
  const job = await waitJob(w, r.json.job_id);
  h.disable();
  assert.equal(job.state, 'failed');
  out.push(`${JSON.stringify(job.error)} total=${performance.now()-t0} maxLag=${h.max/1e6}`);
}

const boot = async (adminKeys) => { const s = buildServer({ dataDir: dir, now: () => now, logSink: () => {}, minFreeBytes: 0, adminKeys }); ... };
const a = await boot([H(adm.publicKey)]);
const org = await a.call('POST', '/api/v1/orgs', { name: 'Synthetic', owner_key: { pk: b64u(own.publicKey), alg: 'ed25519' } }, own);
await a.s.stop();
const b = await boot([]); // key removed from config
const st = await b.call('GET', '/api/v1/admin/status', undefined, adm);
const pop = b64u(ed25519Sign(evil.secretKey, new Uint8Array([...utf8(`QV-KEY-v1\0${orgId}\0`), ...evil.publicKey])));
const mint = await b.call('POST', `/api/v1/orgs/${orgId}/keys`, { pk: b64u(evil.publicKey), alg: 'ed25519', role: 'org_owner', pop }, adm);
assert.equal(st.status, 200); assert.equal(mint.status, 201);

const MW = kp('vb04', 'manifest-w1');
class MWorld extends World { override buildManifest() { const m = super.buildManifest(); m.bb.witnesses = [{ name: 'w1', pk: H(MW.publicKey) }]; return m; } }
const w = new MWorld({ seed: 'vb04', n: 3, t: 2, voters: 3, witnessQuorum: 1 });
// setupOrgAndElection, registerVoters, publishManifest (201), ceremony
const cp = (await w.get(`/api/v1/elections/${w.electionId}/log/checkpoint`)).text;
const size = Number(cp.split('\n')[1]); const note = cp.slice(0, cp.indexOf('\n\n') + 1);
const byManifest = await w.req('POST', `/api/v1/elections/${w.electionId}/log/cosignatures`, { checkpoint_size: size, lines: [cosignLine('w1', MW.secretKey, MW.publicKey, note, w.nowSec)] });
const openA = await w.open();
const cfgKey = w.witnesses[0]; // server-config key, same name, not in manifest
const byCfg = await w.req('POST', `/api/v1/elections/${w.electionId}/log/cosignatures`, { checkpoint_size: size, lines: [cosignLine('w1', cfgKey.secretKey, cfgKey.publicKey, note, w.nowSec)] });
const openB = await w.open();
assert.deepEqual(byManifest.json.accepted, []); assert.equal(openA.status, 409);
assert.deepEqual(byCfg.json.accepted, ['w1']); assert.equal(openB.status, 201);

// packages/server/test/verify-b2b2.test.ts (excerpt)
const w = new World({ seed: 'vb2b2-ctl', n: 3, t: 2, voters: 3 });
await w.start(); await w.setupOrgAndElection(); await w.registerVoters(); await w.publishManifest(); await w.ceremony();
assert.equal((await w.open()).status, 201);
const pause = w.multi(w.mh, { proto: PROTO, type: 'control', action: 'pause', reason: 'v' }, [1, 2]);
const resume = w.multi(w.mh, { proto: PROTO, type: 'control', action: 'resume' }, [1, 2]);
assert.equal((await w.post('notice', w.coord[1]!, pause)).status, 201); w.tick();
assert.equal((await w.post('notice', w.coord[2]!, resume)).status, 201); w.tick();
const solo = w.multi(w.mh, { proto: PROTO, type: 'control', action: 'pause', reason: 'v' }, [2]);
assert.equal((await w.post('notice', w.coord[2]!, solo)).status, 422);
const rep = await w.post('notice', w.coord[2]!, pause);
assert.equal(rep.status, 201);
assert.equal((await w.get(`/api/v1/elections/${w.electionId}/state`)).json.phase, 'PAUSED');
w.tick();
assert.equal((await w.cast(0, { budget: ['no'], chair: ['cy'] })).status, 409);
const notices = (await w.fetchLog('notice')).filter((e) => e.rec?.body?.action === 'pause');
assert.equal(notices.length, 2);
assert.equal(JSON.stringify(notices[0]!.rec), JSON.stringify(notices[1]!.rec));
assert.equal((await w.post('notice', w.coord[1]!, resume)).status, 201); // resume replay too

// same test as B2-05, continued
const closeAt = Date.parse(w.manifest.voting_close);
const c = await w.close(); // 2-of-3 election-close marker
const daysEarly = (closeAt - w.clock) / 86_400_000;
assert.equal(c.status, 201);
assert.ok(daysEarly > 7);
w.tick(3600);
const late = await w.cast(1, { budget: ['yes'], chair: ['ann'] });
assert.notEqual(late.status, 201); // 409, voter refused inside the published window

const w = new World({ seed: 'vb2b2-rst', n: 3, t: 2, voters: 2 });
await w.start(); await w.setupOrgAndElection(); await w.registerVoters();
assert.equal((await w.publishManifest()).status, 201);
const db = findDb(w.dir, w.electionId); const snap = join(w.dir, 'snap.sqlite');
await w.server.stop(); copyFileSync(db, snap); await w.start();
assert.equal((await w.post('ceremony_start', w.coord[1]!, w.marker('dkg-open', w.mh))).status, 201);
const a = (await w.get(`/api/v1/elections/${w.electionId}/log/checkpoint`)).text;
await w.server.stop(); copyFileSync(snap, db); rmSync(`${db}-wal`, { force: true }); rmSync(`${db}-shm`, { force: true });
await w.start();
const st = await w.get(`/api/v1/elections/${w.electionId}/state`); w.tick();
assert.equal((await w.post('election_cancel', w.coord[1]!, w.multi(w.mh, { proto: PROTO, type: 'control', action: 'cancel' }, [1, 2]))).status, 201);
const b = (await w.get(`/api/v1/elections/${w.electionId}/log/checkpoint`)).text;
const pa = parseCheckpoint(a), pb = parseCheckpoint(b);
assert.equal(pa.value.size, pb.value.size);
assert.notDeepEqual(Buffer.from(pa.value.root), Buffer.from(pb.value.root));
assert.equal(checkFork(a, b, Buffer.from(w.logPkHex, 'hex')).ok, true); // st.json.integrity === 'ok'

const root = mkdtempSync(join(tmpdir(), 'vb2b2-tr-')); const cwd0 = process.cwd();
const A = join(root, 'electionA'), B = join(root, 'other'); mkdirSync(A); mkdirSync(B);
const out: string[] = [], err: string[] = [];
const io = { out: (s: string) => out.push(s), err: (s: string) => err.push(s), promptSecret: async () => PASS };
const run = (a: string[]) => trusteeMain([...a, '--json'], io, mkDeps('vb2b2'), {});
const bundle = join(A, 'share.qvtb');
assert.equal(await run(['keygen', '--bundle', bundle]), 0);
process.chdir(A);
assert.equal(await run(['backup', '--bundle', bundle, '--to', 'copy.qvtb']), 0);
process.chdir(B);
writeFileSync(join(B, 'copy.qvtb'), 'unrelated synthetic data, not a trustee bundle');
writeFileSync(join(B, 'ac.json'), '{}');
assert.equal(await run(['destroy', '--bundle', bundle, '--audit-close', join(B, 'ac.json'), '--confirm', 'x']), 0);
const rep = JSON.parse(out.pop()!);
assert.deepEqual(rep.backups_removed, ['copy.qvtb']);
assert.equal(existsSync(join(A, 'copy.qvtb')), true);  // real backup survives
assert.equal(existsSync(join(B, 'copy.qvtb')), false); // unrelated file shredded
process.chdir(cwd0);

// packages/server/test/verify-b2b3.test.ts (excerpt)
import { World } from './helpers/world.ts';
const invite = (w, body) => w.signed('POST', `/api/v1/elections/${w.electionId}/invites`, body, w.owner, w.idemKey());
test('V-B2-09 invite cap ignores existing invites', async () => {
  const w = new World({ seed: 'v9', n: 3, t: 2, voters: 0, server: { maxVotersPerElection: 2 } });
  await w.start();
  try {
    await w.setupOrgAndElection();
    let made = 0;
    for (let i = 0; i < 6; i++) { const r = await invite(w, { count: 4 }); if (r.status === 201) made += r.json.invites.length; }
    const l = await w.signed('GET', `/api/v1/elections/${w.electionId}/invites?limit=500`);
    assert.equal(made, 24); assert.equal(l.json.items.length, 24);
    assert.equal((await invite(w, { count: 5 })).status, 429); // only per-request size bounded
  } finally { await w.stop(); }
});

const reg = (w, code, k) => w.req('POST', `/api/v1/elections/${w.electionId}/registrations`, {
  invite_code: code, pk: b64u(k.publicKey), alg: 'ed25519',
  pop: b64u(ed25519Sign(k.secretKey, new Uint8Array([...utf8(`QV-REG-v1\0${w.electionId}\0`), ...k.publicKey]))) });
test('V-B2-10', async () => {
  const w = new World({ seed: 'v10', n: 3, t: 2, voters: 0 }); await w.start();
  try {
    await w.setupOrgAndElection();
    const codes = (await invite(w, { count: 3 })).json.invites.map((x) => x.code);
    const [k1, k2, k3] = [kp('v10','a'), kp('v10','b'), kp('v10','c')];
    w.clock += 400 * 86_400_000;
    assert.equal((await reg(w, codes[0], k1)).status, 201);          // never expires
    const unknown = await reg(w, 'A'.repeat(22), k3);               // 422 INVITE_EXPIRED
    const used = await reg(w, codes[0], k3);                         // 409 INVITE_USED
    assert.equal((await reg(w, codes[1], k2)).status, 201);
    assert.equal((await reg(w, codes[0], k2)).status, 201);          // cross-invite replay
    assert.equal((await invite(w, { count: 1, expires_at: '2099-01-01T00:00:00Z' })).status, 201);
  } finally { await w.stop(); }
});

test('V-B2-11', async () => {
  const w = new World({ seed: 'v11', n: 3, t: 2, voters: 0 }); await w.start();
  try {
    await w.setupOrgAndElection();
    const inv = (await invite(w, { items: [{ label: 'Synthetic A', contact: 'a@example.invalid' }, { label: 'Synthetic B', contact: 'b@example.invalid' }] })).json.invites;
    assert.equal((await reg(w, inv[0].code, kp('v11','x'))).status, 201);
    assert.equal((await w.signed('DELETE', `/api/v1/elections/${w.electionId}/invites/${inv[1].invite_id}`)).status, 204);
    w.clock += 30 * 86_400_000;
    await w.get(`/api/v1/elections/${w.electionId}/roll`);
    const f = readdirSync(w.dir, { recursive: true }).map(String).find((p) => p.includes(w.electionId) && p.endsWith('.sqlite'));
    const db = new DatabaseSync(join(w.dir, f), { readOnly: true });
    const rows = db.prepare('SELECT state, label_enc IS NOT NULL AS l, contact_enc IS NOT NULL AS c FROM voter_invite ORDER BY state').all();
    db.close();
    assert.deepEqual(rows.map((r) => [r.state, r.l, r.c]), [['registered',1,0],['revoked',1,1]]);
  } finally { await w.stop(); }
});

const rcpt = (j) => ({ origin: j.origin, seq: j.seq, leafHash: unb64u(j.leaf_hash), sequencedAt: j.promise.sequenced_at,
  checkpointDeadline: j.promise.checkpoint_deadline, promiseSig: unb64u(j.promise_sig) });
const ZERO_PK = ed25519Keypair(new Uint8Array(32)).publicKey;
test('V-B2-12', { timeout: 300_000 }, async () => {
  const A = await fullElection('v12-src');
  try {
    const logPk = Buffer.from(A.logPkHex, 'hex');
    const e = (await A.get(`/api/v1/elections/${A.electionId}/log/entries?from=2&limit=1`)).json.entries[0];
    const bytes = await exportQvb(A);
    await A.server.stop(); await A.start();           // reload ARCHIVED runtime: keys erased
    const re = await A.req('POST', `/api/v1/elections/${A.electionId}/log/entries`, { header: e.header_b64u, body: e.body_b64u });
    assert.equal(verifyReceipt(rcpt(re.json.receipt), logPk).ok, false);
    assert.equal(verifyReceipt(rcpt(re.json.receipt), ZERO_PK).ok, true);
    const B = new World({ seed: 'v12-dst', n: 3, t: 2, voters: 0 }); await B.start();
    try {
      await B.setupOrgAndElection();
      const job = await importAndWait(B, bytes); assert.equal(job.state, 'done');
      const m = await B.req('POST', `/api/v1/elections/${job.result.election_id}/log/entries`, { header: e.header_b64u, body: e.body_b64u });
      assert.equal(verifyReceipt(rcpt(m.json.receipt), logPk).ok, false);
      assert.equal(verifyReceipt(rcpt(m.json.receipt), ZERO_PK).ok, true);
    } finally { await B.stop(); }
  } finally { await A.stop(); }
});

// packages/server/test/verify-b2b4.test.ts (excerpt)
test('V-B2-13', { timeout: 180_000 }, async () => {
  const w = new World({ seed: 'vb4-roll', n: 3, t: 2, voters: 4 });
  w.voters.sort((a, b) => Buffer.compare(Buffer.from(b.publicKey), Buffer.from(a.publicKey))); // enrol in descending pk order
  await w.start();
  try {
    await w.setupOrgAndElection();
    await w.registerVoters();
    assert.equal((await w.publishManifest()).status, 201);
    await w.ceremony(); // includes roll_commit
    const r = await w.get(`/api/v1/elections/${w.electionId}/roll`); // anonymous
    const items = r.json.items;
    assert.ok(r.json.roll_root);
    assert.deepEqual(items.map((i) => i.pk), w.voters.map((v) => b64u(v.publicKey))); // == enrolment order
    assert.deepEqual(items.map((i) => i.roll_index), [3, 2, 1, 0]); // pk order is the reverse
  } finally { await w.stop(); }
});

test('V-B2-14', async () => {
  const w = new World({ seed: 'vb4-cos', n: 3, t: 2, voters: 1 });
  await w.start();
  try {
    await w.setupOrgAndElection();
    assert.equal((await w.publishManifest()).status, 201);
    const url = `/api/v1/elections/${w.electionId}/export.qvb`;
    const e0 = (await w.get(url)).headers.get('etag');
    assert.equal(e0, (await w.get(url)).headers.get('etag'));
    for (let k = 0; k < 2; k++) {
      const r = await w.req('POST', `/api/v1/elections/${w.electionId}/log/cosignatures`, { checkpoint_size: 1, lines: ['xxxxxxxxxxxxxxxxxxxx not a cosignature'] });
      assert.equal(r.status, 200);
      assert.deepEqual(r.json.accepted, []);
      assert.deepEqual(r.json.rejected, []);
    }
    const e1 = (await w.get(url)).headers.get('etag');
    assert.notEqual(e0, e1);
    assert.ok(e1.endsWith(':2"'));
  } finally { await w.stop(); }
});

