console.log('child exit code:', exited, 'stderr has destroy TypeError:', /reading 'destroy'/.test(err));

test('V-B2-16', { timeout: 240_000 }, async () => {
  const w = new World({ seed: 'vb4-log', n: 3, t: 2, voters: 3 });
  await w.start();
  try {
    await w.setupOrgAndElection(); await w.registerVoters(); await w.publishManifest(); await w.ceremony();
    assert.equal((await w.open()).status, 201);
    w.clock += 37_000;
    const from = w.logs.length;
    assert.equal((await w.cast(0, { budget: ['yes'], chair: ['ann'] })).status, 201);
    const lines = w.logs.slice(from).map((l) => JSON.parse(l));
    const app = lines.find((l) => l.event === 'append' && l.entry_type === 'ballot');
    const req = lines.find((l) => l.event === 'request' && l.method === 'POST' && /log\/entries/.test(l.route));
    assert.match(app.ts, /:00Z$/);
    assert.doesNotMatch(req.ts, /:00Z$/);
    assert.equal(req.n, app.n + 1);
    assert.equal(req.election_id, w.electionId);
    for (const f of ['request_id', 'latency_ms', 'bytes_in', 'election_id']) assert.ok(f in req);
  } finally { await w.stop(); }
});

// packages/server/test/verify-b2-17.test.ts
import test, { after, before } from 'node:test';
import assert from 'node:assert/strict';
import { World } from './helpers/world.ts';
let w: World; let calls = 0;
before(async () => {
  w = new World({ seed: 'verify-b2-17', n: 3, t: 2, voters: 2 });
  await w.start(); await w.setupOrgAndElection(); await w.publishManifest();
  const rt = (await w.server.pool.get(w.electionId))!;
  const orig = rt.edb.entries.bind(rt.edb);
  rt.edb.entries = ((from: number, n: number) => { calls++; return orig(from, n); }) as typeof rt.edb.entries;
}, { timeout: 60_000 });
after(async () => { await w.stop(); });
const count = async (p: string, h: Record<string, string> = {}) => {
  const b = calls; const r = await fetch(w.base + p, { headers: h }); await r.arrayBuffer();
  return { status: r.status, etag: r.headers.get('etag')!, scans: calls - b };
};
test('export.json: 304 and 206 each re-scan the full log', async () => {
  const p = `/api/v1/elections/${w.electionId}/export.json`;
  const full = await count(p); assert.equal(full.status, 200); assert.ok(full.scans >= 1);
  const nm = await count(p, { 'if-none-match': full.etag }); assert.equal(nm.status, 304); assert.ok(nm.scans >= 1);
  const rg = await count(p, { range: 'bytes=0-9' }); assert.equal(rg.status, 206); assert.ok(rg.scans >= 1);
});
test('export.qvb (control): cached', async () => {
  const p = `/api/v1/elections/${w.electionId}/export.qvb`;
  const full = await count(p); assert.equal(full.status, 200);
  const nm = await count(p, { 'if-none-match': full.etag }); assert.equal(nm.status, 304); assert.equal(nm.scans, 0);
  const rg = await count(p, { range: 'bytes=0-9' }); assert.equal(rg.status, 206); assert.equal(rg.scans, 0);
});

// packages/trustee/test/verify-tr0708.test.ts
import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, symlinkSync, readFileSync, existsSync, lstatSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { shred } from '../src/fsutil.ts';
import { Trustee } from '../src/trustee.ts';
test('shred on a symlinked path overwrites the unrelated target and only unlinks the link', async () => {
  const d = mkdtempSync(join(tmpdir(), 'vtr08-'));
  const victim = join(d, 'unrelated-notes.txt');
  writeFileSync(victim, 'SYNTHETIC-UNRELATED-CONTENT');
  const backup = join(d, 'share.backup.qvbundle');
  symlinkSync(victim, backup);
  const ok = await shred(backup, (n) => new Uint8Array(n).fill(0x41));
  assert.equal(ok, true);
  assert.equal(existsSync(victim), true);
  assert.equal(readFileSync(victim, 'utf8'), 'A'.repeat(27)); // overwritten, no QVBUNDL1 magic check
  assert.throws(() => lstatSync(backup)); // only the link is unlinked
});
test('debugPlaintext is a public instance method', () => {
  assert.equal(typeof (Trustee as unknown as { prototype: Record<string, unknown> }).prototype['debugPlaintext'], 'function');
});

// vpoc/v01.test.ts (abridged)
import assert from 'node:assert/strict'; import { test } from 'node:test';
import { bytesToHex as H } from '../packages/crypto/src/index.ts';
import { NO_SUPERSEDES, buildBallot, makeCast, makeSpoil, verifyElection, analyzeBallotLog } from '../packages/protocol/src/index.ts';
import { bundleOf, castBallot, closeElection, publishTally, push, setup, voterEnvelopes } from '../packages/protocol/test/helpers/sim.ts';
const yn = { id:'q', title:'Q?', method:'yes-no', options:[{id:'yes',label:'Y'},{id:'no',label:'N'}], selection_limit:1, min_selections:0, rule:{type:'threshold',num:1,den:2,basis:'yes+no',strict:true}, tie_break:{type:'status-quo',option:'no'} };
for (const maxSpoils of [0,1]) test(`over-limit ${maxSpoils}`, async () => {
  const s = await setup({ seed:`v01-${maxSpoils}`, n:3, t:2, voters:3, contests:[yn], maxSpoils });
  const p = s.params!, v = s.voters[0]!;
  for (let i=0;i<maxSpoils;i++){ const f=buildBallot(p,v.secretKey,v.publicKey,NO_SUPERSEDES,{q:['no']},s.rng,0); if(f.ok) push(s, makeSpoil(p,v.secretKey,f.value,'publish')); }
  const b = buildBallot(p,v.secretKey,v.publicKey,NO_SUPERSEDES,{q:['yes']},s.rng,0); if(!b.ok) return;
  push(s, makeSpoil(p,v.secretKey,b.value,'publish')); push(s, makeCast(p,v.secretKey,b.value));
  s.lastCode.set(H(v.publicKey), H(b.value.code));
  castBallot(s,1,{q:['no']}); castBallot(s,2,{q:['no']}); closeElection(s);
  const an = analyzeBallotLog(p,new Set(s.rollHex),voterEnvelopes(s),s.openSeq!,s.closeSeq!);
  assert.equal(an.spoiled.has(H(b.value.code)), false);
  publishTally(s,[1,2]);
  const r = await verifyElection(JSON.parse(JSON.stringify(bundleOf(s))));
